    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    wall = max((v for v in counts if v != bg), key=lambda v: counts[v])

    comp = [[-1] * w for _ in range(h)]
    labels = []
    marker_counts = []
    marker_cells = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == wall or comp[r][c] != -1:
                continue
            k = len(labels)
            q = deque([(r, c)])
            comp[r][c] = k
            freq = Counter()
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if grid[y][x] != bg:
                    freq[grid[y][x]] += 1
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w
                            and grid[yy][xx] != wall
                            and comp[yy][xx] == -1):
                        comp[yy][xx] = k
                        q.append((yy, xx))
            marker_counts.append(freq)
            marker_cells.append([p for p in cells if grid[p[0]][p[1]] != bg])
            labels.append(max(freq, key=lambda color: (freq[color], -color))
                          if freq else None)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != wall:
                continue
            candidates = {}
            for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                y, x = r + dy, c + dx
                if not (0 <= y < h and 0 <= x < w):
                    continue
                k = comp[y][x]
                color = labels[k]
                if color is None:
                    continue
                d = min(abs(r-a) + abs(c-b) for a, b in marker_cells[k])
                if color not in candidates or d < candidates[color]:
                    candidates[color] = d
            if candidates:
                out[r][c] = min(candidates, key=lambda color: (candidates[color], -color))
    return out
