from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    separator = max((v for v in counts if v != background),
                    key=lambda v: counts[v])

    sources = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] not in (background, separator)]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != separator:
                continue
            nearest = h + w + 1
            colors = set()
            for y, x, color in sources:
                d = abs(r - y) + abs(c - x)
                if d < nearest:
                    nearest = d
                    colors = {color}
                elif d == nearest:
                    colors.add(color)
            if len(colors) == 1:
                out[r][c] = next(iter(colors))
    return out
